  {verify : Etna.Design.Anchorless.HopProof → Bool} {stored : Nat → Nat → Nat → Nat → Prop}
  {request : Etna.Design.Anchorless.ServiceRequest} {proof : Option Etna.Design.Anchorless.HopProof},
  Etna.Design.Anchorless.InstallRun fork installation →
    Etna.Design.Anchorless.ServiceRun config l1 fork verify s cache →
      Etna.Design.Anchorless.StorageSound l1 verify stored →
        Etna.Design.Anchorless.serviceAuthorize config installation s cache verify request proof = Bool.true →
          request.sourceChain = config.domain.chain ∧
            ∃ number,
              stored number request.sourceChain config.domain.signalService
                (config.slotOf request.sourceChain request.app request.signal)

