  {p : Etna.Design.Reconstruction.Point} {state : Etna.Design.Reconstruction.Bytes}
  {blocks : List Etna.Design.Reconstruction.PublicBlock} {out : Etna.Design.Reconstruction.Executed},
  Etna.Design.Reconstruction.Execution el p state blocks out →
    Etna.Design.Reconstruction.executeSuffix el p state blocks = Option.some out

