  {p : Etna.Design.Reconstruction.Point} {state : Etna.Design.Reconstruction.Bytes}
  {archive : List (Nat × Etna.Design.Reconstruction.Bytes)} {blocks : List Etna.Design.Reconstruction.PublicBlock}
  {out : Etna.Design.Reconstruction.Executed},
  Etna.Design.Reconstruction.Stored el base p state archive →
    Etna.Design.Reconstruction.Execution el p state blocks out →
      Etna.Design.Reconstruction.Stored el base out.point out.state (out.headers.reverse ++ archive)

∀ {el : Etna.Design.Reconstruction.Primitives}
  (laws : Etna.Design.Reconstruction.ProjectionLaws el) {r : Etna.Design.BlockValidity.Rules}
  {p : Etna.Design.BlockValidity.Header} {bs : List Etna.Design.BlockValidity.Block}
  {archive : List (Nat × Etna.Design.Reconstruction.Bytes)},
  Etna.Design.BlockValidity.Chain r p bs →
    laws.guestRules r →
      (∀ (b : Etna.Design.BlockValidity.Block),
          b ∈ bs → Option.map el.headerHash (List.lookup b.header.height archive) = Option.some b.header.elHash) →
        Etna.Design.Reconstruction.verifyOverlap el archive { height := p.height, elHash := p.elHash }
            (List.map laws.project bs) =
          Option.some
            { height := (Etna.Design.BlockValidity.terminal p bs).height,
              elHash := (Etna.Design.BlockValidity.terminal p bs).elHash }

∀ {el : Etna.Design.Reconstruction.Primitives}
  {laws : Etna.Design.Reconstruction.ProjectionLaws el} {s t : Etna.Design.Reconstruction.Rebuilt}
  {records : List Etna.Design.Reconstruction.Record},
  Etna.Design.Reconstruction.ProjectionTrace el laws s records t →
    Etna.Design.Reconstruction.reconstruct el s records = Option.some t

∀ {el : Etna.Design.Reconstruction.Primitives}
  {a : Etna.Design.Reconstruction.Start} {header state : Etna.Design.Reconstruction.Bytes}
  {s : Etna.Design.Reconstruction.Rebuilt},
  Etna.Design.Reconstruction.initializeState el a header state = Option.some s →
    Etna.Design.Reconstruction.Stored el s.baseHeight { height := s.checkpoint.height, elHash := s.checkpoint.elHash }
        s.state s.archive ∧
      s.checkpoint = a.checkpoint ∧ el.stateRoot s.state = a.stateRoot

∀ {el : Etna.Design.Reconstruction.Primitives}
  {laws : Etna.Design.Reconstruction.ProjectionLaws el} {s : Etna.Design.Reconstruction.Rebuilt}
  {l : Etna.Design.Reconstruction.Landing} (cert : Etna.Design.Reconstruction.Certification el laws s l),
  ∃ out,
    Etna.Design.Reconstruction.reconstructLanding el s l = Option.some (Etna.Design.Reconstruction.finish s l out) ∧
      out.applied.Nodup ∧ ∀ (h : Nat), h ∈ out.applied ↔ s.checkpoint.height < h ∧ h ≤ l.input.lastHeight

∀ {el : Etna.Design.Reconstruction.Primitives}
  {laws : Etna.Design.Reconstruction.ProjectionLaws el} {s t : Etna.Design.Reconstruction.Rebuilt}
  {records : List Etna.Design.Reconstruction.Record},
  Etna.Design.Reconstruction.ProjectionTrace el laws s records t →
    s.checkpoint.height ≤ t.checkpoint.height ∧
      t.applied = s.applied ++ List.range' (s.checkpoint.height + 1) (t.checkpoint.height - s.checkpoint.height)

